```java
public class RoutingDataSource extends AbstractRoutingDataSource {
    @Override
    protected Object determineCurrentLookupKey() {
        return TransactionSynchronizationManager.isCurrentTransactionReadOnly()
               ? "READ" : "WRITE";
    }
}

@Configuration
public class DataSourceConfig {
    @Bean
    public DataSource dataSource() {
        Map<Object, Object> targetDataSources = new HashMap<>();
        targetDataSources.put("WRITE", primaryDataSource());
        targetDataSources.put("READ", replicaDataSource());

        RoutingDataSource routingDataSource = new RoutingDataSource();
        routingDataSource.setTargetDataSources(targetDataSources);
        routingDataSource.setDefaultTargetDataSource(primaryDataSource());
        routingDataSource.afterPropertiesSet();
        // ⚠️ Without this wrapper the connection is taken BEFORE @Transactional(readOnly = true)
        // is applied, so every query would go to the primary.
        return new LazyConnectionDataSourceProxy(routingDataSource);
    }
}

@Service
public class OrderService {

    // Goes to REPLICA (192.168.1.50)
    @Transactional(readOnly = true)
    public List<Order> getAllOrders() {
        return orderRepository.findAll();
    }

    // Goes to PRIMARY (192.168.1.10)
    @Transactional
    public void createOrder(Order order) {
        orderRepository.save(order);
    }
}
```

