function Search() {
  const search = useMemo(
    () => debounce((term) => fetch(`/api/search?q=${encodeURIComponent(term)}`), 300),
    []
  );
  useEffect(() => () => search.cancel(), [search]);   // cleanup

  return <input onChange={(e) => search(e.target.value)} />;
}
```

