export interface User {
  id: number;
  name: string;
  email: string;
  phone: string;
}

@Injectable({ providedIn: "root" })
export class UserService {
  private usersSubject = new BehaviorSubject<User[]>([]);
  readonly users$ = this.usersSubject.asObservable();   // 🔒 Read-only stream

  private apiLoaded = false;                            // 🚦 Cache flag

  constructor(private http: HttpClient) {}

  loadUsers() {
    if (this.apiLoaded) return;                         // ✅ Skip if already loaded / loading
    this.apiLoaded = true;                              // set BEFORE the call: a second quick call won't fetch again

    this.http
      .get<User[]>("https://jsonplaceholder.typicode.com/users")
      .subscribe({
        next: (users) => this.usersSubject.next(users),
        error: () => (this.apiLoaded = false),          // allow a retry if it failed
      });
  }

  addUser(user: User) {
    this.usersSubject.next([...this.usersSubject.value, user]);
  }

  updateUser(updated: User) {
    const users = this.usersSubject.value.map((u) =>
      u.id === updated.id ? updated : u,
    );
    this.usersSubject.next(users);
  }

  deleteUser(id: number) {
    this.usersSubject.next(this.usersSubject.value.filter((u) => u.id !== id));
  }

  getUserById(id: number): User | undefined {
    return this.usersSubject.value.find((u) => u.id === id);
  }
}

